  201 func (z *Zone) DrawCard() (*Card, error) {
  202 	if z.Type != ZoneLibrary {
  203 		return nil, errors.New("can only draw from library")
  204 	}
  205 	if z.IsEmpty() {
  206 		return nil, errors.New("cannot draw from empty library")
  207 	}
  208 	// Draw from top (index 0)
  209 	card := z.Cards[0]
  210 	z.Cards = z.Cards[1:]
  211 	return card, nil
  212 }

### backend/game/ability_effects.go:16301-16335 [game.GameState.executeDrawEffect; f8d04f3ce658cafd9fc05a92edd2960e016e36d9]
16301 func (gs *GameState) executeDrawEffect(controller int, effectValue map[string]interface{}, targets []Target) error {
16302 	amount := getIntValue(effectValue, "amount", 1)
16303 	if amount < 0 {
16304 		amount = 0
16305 	}
16306 
16307 	if targetType, ok := effectValue["target"].(string); ok && targetType == "each_player" {
16308 		for playerIdx := range gs.Players {
16309 			if err := gs.DrawCardsWithEvent(playerIdx, amount); err != nil {
16310 				return err
16311 			}
16312 		}
16313 		return nil
16314 	}
16315 
16316 	// draw_target_player primitive (ticket #3241, REPARSE-MAP
16317 	// verb_unmapped:p_draw / "target player"/"that player" family): a
16318 	// player-type target — either interactively chosen for "target player
16319 	// draws a card" (Lore Weaver, Xira Arien; ActivatedAbility.Target is
16320 	// already wired into stackObj.Targets) or bound via a target_ref
16321 	// rewrite like event_player for "that player" (Archivist of Gondor's
16322 	// monarch end-step trigger; see ExecuteAbilityEffect above) — overrides
16323 	// the controller/opponent default below.
16324 	for _, t := range targets {
16325 		if !t.IsCard && t.PlayerIdx >= 0 && t.PlayerIdx < len(gs.Players) {
16326 			return gs.DrawCardsWithEvent(t.PlayerIdx, amount)
16327 		}
16328 	}
16329 
16330 	targetPlayer := controller
16331 	if targetType, ok := effectValue["target"].(string); ok && targetType == "opponent" {
16332 		targetPlayer = 1 - controller
16333 	}
16334 	return gs.DrawCardsWithEvent(targetPlayer, amount)
16335 }

### backend/game/player.go:1982-1990 [game.Player.DrawCard; f8d04f3ce658cafd9fc05a92edd2960e016e36d9]
 1982 func (p *Player) DrawCard() error {
 1983 	card, err := p.Library.DrawCard()
 1984 	if err != nil {
 1985 		// Rule 104.3c - If a player is required to draw more cards than are left in their library, they lose
 1986 		return fmt.Errorf("player %d tried to draw from empty library", p.Index)
 1987 	}
 1988 	p.Hand.AddCard(card)
 1989 	return nil
 1990 }

